head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vBzProcsNo = "";      // [부모 data] 회사 업무처리번호 — 비어 있으면 신규 (AS-IS parentWin.clickBzProcsNo)
scwin.isurCd = "";          // [부모 data] 선택 행 회사코드
scwin.comNm = "";           // [부모 data] 선택 행 회사명
scwin.listDd = "";          // [부모 data] 선택 행 상장일
scwin.newSecugrpId = "";    // [부모 data] 신규 증권그룹ID — 부모의 신규 증권그룹 콤보 값
scwin.trJob = "";           // 처리구분 I: 저장 (원본 TR_JOB)
scwin.userMkt = "";         // 사용자 시장구분 1: 유가증권, 2: 코스닥 (세션 market)
scwin.newMktTpCd = "";      // 신규 건 시장구분 기본값 (원본 pJsMarket — 유가·코스닥 외 사용자는 "A")
// 원본 : /kindstk/ULDSTF05103.gfm (주권 종류주식 상장심사관리 팝업) — gfm 은 저장소에 없고, W-Craft 1차 변환에 API 적용까지 마친 개발 사본으로 분석했다.
/*
 * 화면 동작
 *  - 부모(ULDSTF05102 종류주식 상장심사)가 넘긴 업무처리번호가 있으면 기존 건, 없으면 신규다.
 *  - 신규: [회사코드 찾기](ULDSTF05112)로 회사를 고르면 법인정보·상장종목현황을 받는다. 상장일을 넣고 [저장]하면
 *          업무처리번호를 새로 받아 등록하고, 그 번호로 다시 조회한다.
 *  - 기존: 업무처리번호로 법인정보·상장종목현황을 조회한다. 상장일이 지났거나, 보통주 상장심사·금감원코드가 없거나,
 *          심사 부서가 아니면 저장을 잠근다.
 *  - [상장종목신규]·그리드 더블클릭 → 종목 등록(보호예수 포함 ULDSTF05105 / 비포함 ULDSTF05113),
 *    [안내문작성] → 공시안내문작성(ULDSTF92024).
 *  - 통신은 화면에 적용된 API(경로·method·keyInfo)를 명세로 간주한다(사용자 결정 2026-10-29).
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF05103/ULDSTF05103.md (§번호는 이 문서의 절)
 */

// 고정값
// 저장할 수 있는 심사 부서 — 원본 depCd 비교 13건(심사1팀·심사2팀 등). 그 밖의 부서는 저장 잠금 (§6.4)
scwin.EXAM_DEP_CDS = ["2500", "2520", "2540", "3300", "3320", "3330", "3E00", "3E10", "3E20", "3E30", "3E40", "2615", "3G20"];
// 공시안내문 서식코드 — 시장구분별 (AS-IS arr[0])
scwin.DSCL_FORM_CD = { "1" : "68157", "2" : "70735" };

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다.
scwin.BTN_MAP = {
    save : "btn_save"           // [저장]
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 29
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05103.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 29
 * @description 로딩 — 사용자 시장별 화면 → 공통 코드·주거래은행 → 파라미터 수신 → 달력 바인딩 → 기존 건 조회 또는 신규 준비.
 * 콤보 목록을 먼저 받아야 조회 값이 콤보에 표시되므로 코드 조회를 await 한 뒤 조회한다. (원본 gform onload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 사용자 시장별 화면 — 유가(KSE)·코스닥(KOSDAQ) 전용 항목
    scwin.userMkt = String($c.session.getUserInfo("market") ?? "");
    scwin.applyMktView();

    // 2) 공통 코드·주거래은행 목록 (원본 fn_searchCode, fn_SetComboCode)
    await scwin.selectCode();
    await scwin.selectMaintradeBank();

    // 3) 파라미터 수신 — 원본 parentWin.clickBzProcsNo·isurCd·comNm·listDd·newSecugrpId (§1.2)
    const param = $c.data.getParameter() ?? {};
    scwin.vBzProcsNo = param.bzProcsNo ?? "";
    scwin.isurCd = param.isurCd ?? "";
    scwin.comNm = param.comNm ?? "";
    scwin.listDd = param.listDd ?? "";
    scwin.newSecugrpId = param.newSecugrpId ?? "";

    // 4) 달력 검사(규칙 37) — 단일 달력은 checkCalendarFormat, 존립기간은 기간 쌍
    $c.date.checkCalendarFormat(cal_foundDd, "yyyyMMdd");
    $c.date.checkCalendarFormat(cal_stkcertListApprovDd, "yyyyMMdd");
    $c.date.checkCalendarFormat(cal_listDd, "yyyyMMdd");
    $c.date.checkCalendarFormat(cal_oldListDd, "yyyyMMdd");
    $c.date.checkCalendarFormat(cal_oldDelistDd, "yyyyMMdd");
    $c.date.compareFromToDate(cal_exstStrtDd, cal_exstEndDd, ["존립기간 시작일", "존립기간 종료일"]);

    // 5) [상장종목신규]·[안내문작성] — 회사 업무처리번호가 있을 때만 (원본 fn_btnShow)
    scwin.setIsuNewButton();

    // 6) 기존 건 조회 / 신규 준비
    if (!$c.util.isEmpty(scwin.vBzProcsNo)) {
        // 조회 조건(회사코드·상장일)은 부모가 넘긴 선택 행 값 — 원본도 화면에 먼저 채운 뒤 조회했다
        ibx_searchCd.setValue(scwin.isurCd);
        ibx_searchNm.setValue(scwin.comNm);
        dma_corpInfoRes.set("isurCd", scwin.isurCd);
        dma_corpInfoRes.set("listDd", scwin.listDd);

        await scwin.readSync();

        ibx_searchCd.setValue(dma_corpInfoRes.get("isurCd"));
        ibx_searchNm.setValue(dma_corpInfoRes.get("comNm"));

        // SPAC 이면 존립기간을 보인다 (원본 20100528)
        if (sbx_spacYn.getValue() === "Y") {
            panel_spac.show("");
        } else {
            panel_spac.hide();
        }
    } else {
        panel_spac.hide();
        dma_corpInfoRes.set("secugrpId", scwin.newSecugrpId);       // 부모의 신규 증권그룹
        dma_corpInfoRes.set("spotIsuTrdMktTpCd", scwin.newMktTpCd); // 사용자 시장
        $c.util.setButtonState("grp_btnBox", "insert", scwin.BTN_MAP);
    }
    scwin.applyMktLabel();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_coSearch_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 회사코드 찾기 클릭 — 증권그룹이 있어야 신규상장 법인 선택 팝업을 연다. (§4, §1.4 업무 2)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_coSearch_onclick = async function (e) {
    try {
        if ($c.util.isEmpty(sbx_secugrpId.getValue())) {
            await $c.win.alert("[유가증권]을 선택하세요.");
            return;
        }
        await scwin.openCorpPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05103.btn_coSearch_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_isuNew_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 상장종목신규 클릭 — 유가(1)·전체(9) 사용자는 보호예수 포함 종목 등록, 그 밖은 비포함 종목 등록을 신규로 연다. (§4, §1.4 업무 5)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_isuNew_onclick = async function (e) {
    try {
        await scwin.openIsuPopup(-1, scwin.isProtectReg(true));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05103.btn_isuNew_onclick" });
    }
};

/**
 * @method
 * @name scwin.grd_issList_oncelldblclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 상장종목현황 더블클릭 — 유가(1) 사용자는 보호예수 포함, 그 밖은 비포함 종목 등록을 그 종목으로 연다. (§4, §1.4 업무 5)
 * @param {Number} rowIndex 행 번호
 * @param {Number} columnIndex 열 번호
 * @param {String} columnId 열 id
 * @returns
 * @hidden N
 */
scwin.grd_issList_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.openIsuPopup(rowIndex, scwin.isProtectReg(false));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05103.grd_issList_oncelldblclick" });
    }
};

/**
 * @method
 * @name scwin.btn_listNo_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 상장번호생성 클릭 — 사용자 시장의 새 상장번호를 받아 채운다. (§4, §1.4 업무 4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_listNo_onclick = async function (e) {
    try {
        await scwin.selectNewListNo();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05103.btn_listNo_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_save_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 저장 클릭. (§4, §1.4 업무 3)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_save_onclick = async function (e) {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05103.btn_save_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_dscl_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 안내문작성 클릭. (§4, §1.4 업무 6)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_dscl_onclick = async function (e) {
    try {
        await scwin.writeDscl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05103.btn_dscl_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectCode
 * @author Inswave
 * @date 2026. 10. 29
 * @description 공통 코드 6종을 한 번에 받는다 — 명의개서대행기관·시장구분·외부감사인·소속부·상장구분·기업구분. (원본 fn_searchCode — §5.1)
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.selectCode = async function () {
    dma_codReq.set("codeList", "TRANSSTK_AGNT_CD, SPOT_ISU_TRD_MKT_TP_CD, EXT_AUDTR_CD, SECT_TP_CD, LIST_CLSS_CD, PRELM_INVSTG_COM_TP_CD");
    const sbmOptions = {
        id : "sbm_listCodeValue",
        action : "/api/listing/common/code/list-code-value",
        method : "get",
        ref : "dma_codReq",
        target : "dlt_transstkAgntCd=body.TRANSSTK_AGNT_CD, dlt_spotIsuTrdMktTpCd=body.SPOT_ISU_TRD_MKT_TP_CD, dlt_extAudtrCd=body.EXT_AUDTR_CD"
            + ", dlt_sectTpCd=body.SECT_TP_CD, dlt_listClssCd=body.LIST_CLSS_CD, dlt_prelmInvstgComTpCd=body.PRELM_INVSTG_COM_TP_CD",
        isProcessMsg : false
    };
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    return result.responseJSON?.success === true;
};

/**
 * @method
 * @name scwin.selectMaintradeBank
 * @author Inswave
 * @date 2026. 10. 29
 * @description 주거래은행 목록을 받는다. (원본 fn_SetComboCode — §5.2)
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.selectMaintradeBank = async function () {
    const sbmOptions = {
        id : "sbm_listMaintradeBank",
        action : "/api/listing/common/code/list-maintrade-bank",
        method : "get",
        target : "dlt_listMaintradeBank=body",
        isProcessMsg : false
    };
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;
    return result.responseJSON?.success === true;
};

/**
 * @method
 * @name scwin.selectCorpInfo
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신규상장할 회사의 법인정보를 회사코드로 받고 화면 상태를 정한다. (원본 fn_readKindStkNewRegNewList + dts_Corp OnLoadCompleted — §5.3)
 * @param {String} isurCd 회사코드
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.selectCorpInfo = async function (isurCd) {
    dma_corpInfoReq.set("isurCd", isurCd);
    const sbmOptions = {
        id : "sbm_selectCorpInfo",
        action : "/api/listing/lstproc/realship/newlisting/select-corpinfo-byisurcd",
        method : "get",
        ref : "dma_corpInfoReq",
        target : "dma_corpInfoRes=body",
        isProcessMsg : false
    };
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;
    if (!result.responseJSON?.success) return false;    // 실패 안내는 공통 오류 처리(원본 OnLoadError)

    await scwin.applyCorpState();
    return true;
};

/**
 * @method
 * @name scwin.selectDetail
 * @author Inswave
 * @date 2026. 10. 29
 * @description 상장종목현황(그리드)과, 회사 업무처리번호가 있으면 법인정보까지 한 번에 조회한다.
 * 업무처리번호가 없는 신규 건은 법인정보를 회사 조회(select-corpinfo-byisurcd) 값으로 두고 종목만 받는다. (원본 fn_read_sync·fn_kindStkIsuDtl — §5.4)
 * @param {String} isurCd 회사코드
 * @param {String} listDd 상장일
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.selectDetail = async function (isurCd, listDd) {
    const withCorp = !$c.util.isEmpty(scwin.vBzProcsNo);

    dma_selectOneReq.setJSON({
        bzProcsNo : scwin.vBzProcsNo,
        isurCd : isurCd,
        listDd : listDd
    });
    const sbmOptions = {
        id : "sbm_selectOne",
        action : "/api/listing/lstproc/kind/listing-review/stock/select-one",
        method : "get",
        ref : "dma_selectOneReq",
        target : withCorp ? "dlt_isuDetailRes=body.isuDetail, dma_corpInfoRes=body.corpInfo" : "dlt_isuDetailRes=body.isuDetail",
        isProcessMsg : false
    };
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;
    if (!result.responseJSON?.success) return false;

    if (withCorp) await scwin.applyCorpState();
    return true;
};

/**
 * @method
 * @name scwin.selectNewListNo
 * @author Inswave
 * @date 2026. 10. 29
 * @description 사용자 시장의 새 상장번호를 받아 법인정보에 채운다. (원본 btn_listNo onclick + sbm_selectNewListNo_submitdone — §5.5)
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.selectNewListNo = async function () {
    dma_selectNewListNoReq.set("spotIsuTrdMktTpCd", scwin.userMkt);
    const sbmOptions = {
        id : "sbm_selectNewListNo",
        action : "/api/listing/lstproc/listinvstg-common/select-new-listno",
        method : "get",
        ref : "dma_selectNewListNoReq",
        target : "dma_selectNewListNoRes=body",
        isProcessMsg : false
    };
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;
    if (!result.responseJSON?.success) return false;

    // TODO: 등록 요청(dma_registerReq)에 상장번호 키가 없다 — 생성한 번호를 서버가 어떻게 저장하는지 확인 (§10 #3)
    dma_corpInfoRes.set("listNo", dma_selectNewListNoRes.get("listNo"));
    return true;
};

/**
 * @method
 * @name scwin.saveTrs
 * @author Inswave
 * @date 2026. 10. 29
 * @description 종류주식 신규상장 회사정보 등록 전송. (원본 fn_trs + trs_Save OnSuccess/OnFail — §5.6)
 * @param {String} bzProcsNo 새로 받은 업무처리번호
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.saveTrs = async function (bzProcsNo) {
    // 원본은 dts_Corp.LIST_PROCS_STAT_CD = '20' 도 채웠으나 등록 요청 키에 없다 (§10 #4)
    dma_registerReq.setJSON({
        bzProcsNo : bzProcsNo,
        listClssCd : dma_corpInfoRes.get("listClssCd"),
        listDd : dma_corpInfoRes.get("listDd"),
        prelmInvstgBzProcsNo : dma_corpInfoRes.get("prelmInvstgBzProcsNo"),
        isurCd : dma_corpInfoRes.get("isurCd"),
        spotIsuTrdMktTpCd : dma_corpInfoRes.get("spotIsuTrdMktTpCd")
    });
    const sbmOptions = {
        id : "sbm_register",
        action : "/api/listing/lstproc/kind/listing-review/stock/register",
        method : "post",
        ref : "dma_registerReq",
        isProcessMsg : false
    };
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    return await scwin.checkResult(result, "저장");
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.readSync
 * @author Inswave
 * @date 2026. 10. 29
 * @description 화면의 회사코드·상장일로 다시 조회한다. (원본 fn_read_sync — §6.1)
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.readSync = async function () {
    return await scwin.selectDetail(dma_corpInfoRes.get("isurCd"), dma_corpInfoRes.get("listDd"));
};

/**
 * @method
 * @name scwin.applyMktView
 * @author Inswave
 * @date 2026. 10. 29
 * @description 사용자 시장별 화면 — 유가는 영문회사심볼, 코스닥은 소속부·기업구분을 보이고 신규 건 시장구분 기본값을 정한다.
 * 지주회사코드 칸은 쓰지 않아 숨긴다. (원본 gform onload — §6.2)
 * @returns
 * @hidden N
 */
scwin.applyMktView = function () {
    panel_HDCOM_ISUR_CD.hide();     // 원본 주석 "미사용?"

    if (scwin.userMkt === "1") {
        panel_KOSDAQ.hide();
        panel_KOSDAQ1.hide();
        panel_KSE.show("");
        scwin.newMktTpCd = "1";
    } else if (scwin.userMkt === "2") {
        panel_KOSDAQ.show("");
        panel_KOSDAQ1.show("");
        panel_KSE.hide();
        scwin.newMktTpCd = "2";
    } else {
        // TODO: 원본 값 "A" 는 시장구분 코드에 없어 신규 건 시장구분이 비어 보인다 (§8 #6)
        scwin.newMktTpCd = "A";
    }
};

/**
 * @method
 * @name scwin.applyMktLabel
 * @author Inswave
 * @date 2026. 10. 29
 * @description 회사의 시장구분에 따라 결산 칸 이름을 바꾼다 — 코스닥(2)은 결산월, 그 밖은 결산기. (원본 sbx_spotIsuTrdMktTpCd OnSelChange — §6.3)
 * @returns
 * @hidden N
 */
scwin.applyMktLabel = function () {
    label_40.setValue(sbx_spotIsuTrdMktTpCd.getValue() === "2" ? "결산월" : "결산기");
};

/**
 * @method
 * @name scwin.applyCorpState
 * @author Inswave
 * @date 2026. 10. 29
 * @description 법인정보를 받은 뒤 화면 상태를 정한다 — 신규면 저장·회사찾기 가능, 기존이면 회사찾기 잠금과 상장일 기준 저장 잠금,
 * 보통주 상장심사·금감원코드·심사 부서 검사. (원본 dts_Corp OnLoadCompleted — §6.4)
 * @returns
 * @hidden N
 */
scwin.applyCorpState = async function () {
    // 회사 조회 응답에 증권그룹이 없으면 부모가 넘긴 신규 증권그룹으로 보충한다
    if ($c.util.isEmpty(dma_corpInfoRes.get("secugrpId"))) {
        dma_corpInfoRes.set("secugrpId", scwin.newSecugrpId);
    }
    scwin.applyMktLabel();

    if ($c.util.isEmpty(scwin.vBzProcsNo)) {
        $c.util.setButtonState("grp_btnBox", "insert", scwin.BTN_MAP);
        scwin.setCoSearchEnabled(true);
    } else {
        scwin.setCoSearchEnabled(false);
        // 상장일 전이면 수정 상태(원본 buttonSet.setUpdateStatus — 이 화면은 버튼이 [저장]뿐이라 저장 잠금), 지났으면 처리 불가
        const curDate = $c.date.getServerDateTime("yyyyMMdd");
        $c.util.setButtonState("grp_btnBox", (cal_listDd.getValue() > curDate) ? "update" : "error", scwin.BTN_MAP);
    }

    if ($c.util.isEmpty(ibx_isurCd.getValue())) {
        await $c.win.alert("보통주 상장심사가 선행되어야 합니다");
        $c.util.setButtonState("grp_btnBox", "error", scwin.BTN_MAP);
        return;
    }
    if (!$c.util.isEmpty(ibx_listNo.getValue())) {
        btn_listNo.setDisabled(true);
    }
    if ($c.util.isEmpty(ibx_fssUnqNo.getValue())) {
        // MSG-0025 "금감원코드가 없어 입력하실수 없습니다."
        await $c.win.alert($c.stf.getMessageParam("MSG-0025", ""));
        $c.util.setButtonState("grp_btnBox", "error", scwin.BTN_MAP);
    }
    // 심사1팀·심사2팀 등 심사 부서만 저장할 수 있다
    if (!scwin.EXAM_DEP_CDS.includes(String($c.session.getUserInfo("depCd") ?? ""))) {
        $c.util.setButtonState("grp_btnBox", "error", scwin.BTN_MAP);
    }
};

/**
 * @method
 * @name scwin.setCoSearchEnabled
 * @author Inswave
 * @date 2026. 10. 29
 * @description 회사코드 찾기 버튼 활성 — 신규만 회사를 고를 수 있다. (원본 fn_initForm C/X — §6.5)
 * @param {Boolean} enabled 활성 여부
 * @returns
 * @hidden N
 */
scwin.setCoSearchEnabled = function (enabled) {
    btn_coSearch.setDisabled(!enabled);
};

/**
 * @method
 * @name scwin.setIsuNewButton
 * @author Inswave
 * @date 2026. 10. 29
 * @description 회사 업무처리번호가 있을 때만 [상장종목신규]·[안내문작성]을 켜고, 없으면 저장 안내 문구를 보인다. (원본 fn_btnShow — §6.5)
 * @returns
 * @hidden N
 */
scwin.setIsuNewButton = function () {
    const hasBzProcsNo = !$c.util.isEmpty(scwin.vBzProcsNo);

    btn_isuNew.setDisabled(!hasBzProcsNo);
    btn_dscl.setDisabled(!hasBzProcsNo);
    if (hasBzProcsNo) {
        lab_btn.hide();
    } else {
        lab_btn.show("");
    }
};

/**
 * @method
 * @name scwin.isProtectReg
 * @author Inswave
 * @date 2026. 10. 29
 * @description 종목 등록을 보호예수 포함 화면(ULDSTF05105)으로 열지 정한다 — 유가(1) 사용자이고 증권그룹이 주권·DR·외국주권이면 포함.
 * 원본은 [상장종목신규]만 전체(9) 사용자도 포함으로 보았다. (원본 btn_isuNew onclick · grd_issList OnDblClick — §6.6)
 * @param {Boolean} withAllMkt 전체(9) 사용자도 포함으로 볼지
 * @returns {Boolean} 보호예수 포함 화면 여부
 * @hidden N
 */
scwin.isProtectReg = function (withAllMkt) {
    const isMkt = (scwin.userMkt === "1") || (withAllMkt && scwin.userMkt === "9");
    return isMkt && ["ST", "DR", "FS"].includes(sbx_secugrpId.getValue());
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 29
 * @description 저장 전 필수 입력 — 상장일·회사코드. 원본은 채번 뒤에 검사했으나 번호를 헛되이 받지 않도록 채번 전에 한다. (원본 fn_trs 머리 — §6.7)
 * @returns {Promise<Boolean>} 통과 여부
 * @hidden N
 */
scwin.validate = async function () {
    // MSG-A005 "[^] 을(를) 입력하셔야 합니다."
    if ($c.util.isEmpty(cal_listDd.getValue())) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "상장일"));
        cal_listDd.focus();
        return false;
    }
    if ($c.util.isEmpty(ibx_isurCd.getValue())) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "회사코드"));
        btn_coSearch.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.checkResult
 * @author Inswave
 * @date 2026. 10. 29
 * @description 등록 응답 판정. 통신 실패이거나 completeYn 이 와서 true 가 아니면 MSG-A002 를 안내하고 false.
 * 등록 API 는 응답 정의가 없어 completeYn 이 오지 않으면 success 만으로 판정한다. (§5.6)
 * @param {Object} result executeDynamic 결과
 * @param {String} jobNm 처리명
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.checkResult = async function (result, jobNm) {
    // TODO: 등록 응답 구조 확인 필요 — completeYn 유무 (§10 #2)
    const completeYn = result.responseJSON?.body?.completeYn;
    const completed = (completeYn === undefined || completeYn === null || String(completeYn) === "true");
    if (result.responseJSON?.success === true && completed) return true;

    await $c.win.alert($c.stf.getMessageParam("MSG-A002", jobNm));
    return false;
};

/**
 * @method
 * @name scwin.getNewBzProcsNo
 * @author Inswave
 * @date 2026. 10. 29
 * @description 업무처리번호를 새로 받는다. $c.stf.getNewBzProcNo 는 응답 봉투를 그대로 돌려줄 수 있어 body 를 꺼내고,
 * body 가 문자열이면 그대로, 객체면 bzProcsNo 를 문자열로 만든다. 14자리 검사는 호출부(scwin.save)가 한다. (§6.8)
 * @returns {Promise<String>} 업무처리번호 (실패면 빈 문자열)
 * @hidden N
 */
scwin.getNewBzProcsNo = async function () {
    // TODO: 채번 응답 모양 미확정 — body 가 문자열인지 { bzProcsNo } 인지 확인 (§10 #5). 지금은 둘 다 받는다.
    const res = await $c.stf.getNewBzProcNo();
    const body = res?.body ?? res;
    return String((typeof body === "object" && body !== null) ? (body.bzProcsNo ?? "") : (body ?? ""));
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 29
 * @description 저장 — 필수 입력 → 확인 → 채번 → 등록 → 안내 → 새 번호로 다시 조회. 등록이 성공한 뒤에만 업무처리번호를 화면에 반영한다. (원본 fn_save — §6.8, §1.4 업무 3)
 * @returns
 * @hidden N
 */
scwin.save = async function () {
    scwin.trJob = "I";

    if (!await scwin.validate()) return;

    // "[저장] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    const bzProcsNo = await scwin.getNewBzProcsNo();
    if (bzProcsNo.length !== 14) {
        // MSG-0010 "업무처리번호생성실패"
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }

    if (!await scwin.saveTrs(bzProcsNo)) return;

    scwin.vBzProcsNo = bzProcsNo;
    await $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));

    // 회사정보 저장 후 [상장종목신규] 활성 (원본 20100910 (2616))
    scwin.setIsuNewButton();
    await scwin.readSync();
};

/**
 * @method
 * @name scwin.openCorpPopup
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신규상장 법인 선택(ULDSTF05112)을 열고, 고른 회사의 법인정보와 상장종목현황을 받는다. 취소·닫기면 아무것도 하지 않는다.
 * (원본 fn_PopFindKindStkExamCorp + fn_SetParIsur — §6.9, 가이드 §6.5)
 * @returns
 * @hidden N
 */
scwin.openCorpPopup = async function () {
    const secugrpId = sbx_secugrpId.getValue();
    const data = {
        isurCd : ibx_searchCd.getValue(),               // AS-IS arr[0]
        isurNm : ibx_searchNm.getValue(),               // AS-IS arr[1]
        secugrpId : secugrpId,                          // AS-IS arr[2]
        mktTpCd : sbx_spotIsuTrdMktTpCd.getValue(),     // AS-IS arr[3]
        searchType : $c.lc.getGlbValue("SEARCH_TYP_SLC")   // AS-IS arr[4]
    };
    const options = {
        id : "ULDSTF05112",
        popupName : $c.lc.getSecuGrpNm(secugrpId) + " 종류주식 신규상장 법인 선택",
        width : 880,
        height : 700,
        frameModal : "top"
    };
    const res = await $c.win.openPopup("/ui/lst/kindstk/ULDSTF05112.xml", options, data);
    if (res?.isCloseButtonClick === true || $c.util.isEmpty(res?.isurCd)) return;

    ibx_searchCd.setValue(res.isurCd);
    ibx_searchNm.setValue(res.comNm ?? "");
    if (!await scwin.selectCorpInfo(res.isurCd)) return;
    await scwin.readSync();
};

/**
 * @method
 * @name scwin.getIsuPopupData
 * @author Inswave
 * @date 2026. 10. 29
 * @description 종목 등록 팝업(ULDSTF05105·05113)에 넘길 값. 원본은 팝업이 이 화면 컴포넌트를 직접 읽었다. (§6.10, 가이드 §6.5)
 * @param {Number} row 선택 행 번호 (신규면 -1)
 * @returns {Object} 넘길 data
 * @hidden N
 */
scwin.getIsuPopupData = function (row) {
    return {
        bzProcsNo : (row >= 0) ? dlt_isuDetailRes.getCellData(row, "bzProcsNo") : "",     // 종목 업무처리번호 (AS-IS clickBzProcsNo)
        coBzProcsNo : scwin.vBzProcsNo,                                                   // 회사 업무처리번호 (AS-IS scwin.vBzProcsNo)
        secugrpId : sbx_secugrpId.getValue(),
        prelmInvstgBzProcsNo : dma_corpInfoRes.get("prelmInvstgBzProcsNo"),
        spotIsuTrdMktTpCd : sbx_spotIsuTrdMktTpCd.getValue(),
        isurCd : ibx_isurCd.getValue(),
        comNm : ibx_comNm.getValue(),
        listDd : cal_listDd.getValue(),
        listClssCd : sbx_listClssCd.getValue(),
        isurSymbl : ibx_isurSymbl.getValue(),
        comAbbrv : dma_corpInfoRes.get("comAbbrv")
    };
};

/**
 * @method
 * @name scwin.openIsuPopup
 * @author Inswave
 * @date 2026. 10. 29
 * @description 종목 등록 팝업을 열고, 저장했거나 X 로 닫혔으면 다시 조회해 보던 행으로 돌아간다.
 * (원본 fn_OpenKindStkDetailCorpIsu_protect · fn_OpenKindStkDetailCorpIsu + 팝업의 parentWin.fn_read_sync·grd_issList.setFocusedCell — §6.10)
 * @param {Number} row 선택 행 번호 (신규면 -1)
 * @param {Boolean} isProtect 보호예수 포함 화면(ULDSTF05105) 여부 — 아니면 ULDSTF05113
 * @returns
 * @hidden N
 */
scwin.openIsuPopup = async function (row, isProtect) {
    const options = {
        id : isProtect ? "ULDSTF05105" : "ULDSTF05113",
        popupName : $c.lc.getSecuGrpNm(sbx_secugrpId.getValue()) + " 종류주식 신규상장 종목등록",
        width : isProtect ? 1180 : 1350,
        height : isProtect ? 880 : 900,
        frameModal : "top"
    };
    const url = isProtect ? "/ui/lst/kindstk/ULDSTF05105.xml" : "/ui/lst/kindstk/ULDSTF05113.xml";
    const res = await $c.win.openPopup(url, options, scwin.getIsuPopupData(row));

    // 저장(isSaved) 또는 X·ESC 닫기(저장 여부를 알 수 없음)면 다시 조회한다
    if (res?.isSaved !== true && res?.isCloseButtonClick !== true) return;
    if (!await scwin.readSync()) return;
    if (row >= 0 && row < dlt_isuDetailRes.getRowCount()) {
        grd_issList.setFocusedCell(row, 0);
    }
};

/**
 * @method
 * @name scwin.checkBiz
 * @author Inswave
 * @date 2026. 10. 29
 * @description 안내문작성 전 확인 — 상장종목이 있어야 한다. (원본 fn_CheckBiz — §6.11)
 * @returns {Promise<Boolean>} 통과 여부
 * @hidden N
 */
scwin.checkBiz = async function () {
    if (dlt_isuDetailRes.getRowCount() === 0) {
        await $c.win.alert("[상장종목]을 입력하세요.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.getDsclTitle
 * @author Inswave
 * @date 2026. 10. 29
 * @description 공시안내문 제목 — "{회사명} 종류주식,  상장일 yyyy.MM.dd". (원본 fn_getKindStkDsclsTitle — §6.11)
 * @param {String} comNm 회사명
 * @param {String} listDd 상장일 (yyyyMMdd)
 * @returns {String} 제목
 * @hidden N
 */
scwin.getDsclTitle = function (comNm, listDd) {
    const dd = String(listDd ?? "");
    return String(comNm ?? "") + " 종류주식,  상장일 " + dd.substring(0, 4) + "." + dd.substring(4, 6) + "." + dd.substring(6, 8);
};

/**
 * @method
 * @name scwin.getDsclData
 * @author Inswave
 * @date 2026. 10. 29
 * @description 공시안내문작성(ULDSTF92024)에 넘길 값. 원본 fn_dscl 이 임시 fn_GetPar 로 채우던 arr[0..3]·arr[5](유가만)와 종목·마스터 데이터셋이다.
 * 마스터에는 종목의 배당기산일·발행가·종목코드·단축코드·발행일(마지막 종목)과 상장구분명을 더한다. (§6.11)
 * @returns {Object} 넘길 data
 * @hidden N
 */
scwin.getDsclData = function () {
    const mktId = String(dma_corpInfoRes.get("spotIsuTrdMktTpCd") ?? "");
    // TODO: 원본 공시용 종목 조회(readDisclsData) API 가 없어 상장종목현황으로 넘긴다 (§10 #6)
    const isuList = dlt_isuDetailRes.getAllJSON();

    // AS-IS arr[1] — 회사 업무처리번호 뒤에 종목 업무처리번호를 콤마로 잇는다
    let bzProcsNo = scwin.vBzProcsNo;
    isuList.forEach(row => {
        bzProcsNo = bzProcsNo + (bzProcsNo === "" ? "" : ",") + (row.bzProcsNo ?? "");
    });

    const lastIsu = isuList[isuList.length - 1] ?? {};
    const mst = {
        ...dma_corpInfoRes.getJSON(),
        divReckDd1 : lastIsu.divReckDd1 ?? "",
        isuPrc : lastIsu.isuPrc ?? "",
        isuCd : lastIsu.isuCd ?? "",
        isuSrtCd : lastIsu.isuSrtCd ?? "",
        isuDd : lastIsu.isuDd ?? "",
        listClssNm : sbx_listClssCd.getText()
    };

    return {
        formCd : scwin.DSCL_FORM_CD[mktId] ?? "",                                     // AS-IS arr[0]
        bzProcsNo : bzProcsNo,                                                         // AS-IS arr[1]
        isurCd : dma_corpInfoRes.get("isurCd"),                                       // AS-IS arr[2]
        mktId : mktId,                                                                 // AS-IS arr[3]
        title : scwin.getDsclTitle(dma_corpInfoRes.get("comNm"), cal_listDd.getValue()),   // AS-IS arr[5] — 유가(1)만 넘긴다
        isu : isuList,                                                                 // AS-IS CopyDataSet(dts_Discls_Isu, param_dts_isu)
        mst : [mst]                                                                    // AS-IS CopyDataSet(dts_Corp, param_dts_mst)
    };
};

/**
 * @method
 * @name scwin.writeDscl
 * @author Inswave
 * @date 2026. 10. 29
 * @description 안내문작성 — 상장종목이 있으면 공시안내문작성 팝업을 data 로 넘겨 열고 닫힐 때까지 기다린다.
 * 원본 개발 사본은 alert 후 return 으로 막혀 있었다. 원본도 닫힌 뒤 다시 조회하지 않는다. (원본 fn_dscl — §6.11, 가이드 §6.5)
 * @returns
 * @hidden N
 */
scwin.writeDscl = async function () {
    if (!await scwin.checkBiz()) return;

    const options = {
        id : "ULDSTF92024",
        popupName : "종류주식 공시안내문작성",
        width : 735,
        height : 815,
        type : "pageFramePopup"
    };

    // TODO: 경로는 가정, 92024 는 아직 getPar 계약이라 수신부 변경 필요 (§10 #7)
    await $c.win.openPopup("/ui/listingcommon/ULDSTF92024.xml", options, scwin.getDsclData());
};

/**
 * @method
 * @name scwin.getPar
 * @author Inswave
 * @date 2026. 10. 29
 * @description [호환용 · 임시] 공시안내문작성(ULDSTF92024) 전환본은 아직 부모의 scwin.getPar 를 이름으로 불러 값을 받는다.
 * 92024 가 $c.data.getParameter() 수신으로 바뀌면 이 함수를 지운다. 원본 arr 길이를 그대로 재현한다 — 유가(1)는 [5] 까지 6,
 * 그 밖은 4(92024 는 arr 길이 5 이상이면 본문을 생성하지 않는다). (§6.11, §10 #7, 가이드 §6.5 예외)
 * @param {Array} arr 92024 가 넘기는 빈 배열 — [0] 서식코드 [1] 업무처리번호 [2] 회사코드 [3] 시장구분 [5] 공시제목(유가만)
 * @param {Object} dltIsu 92024 의 종목 dataList
 * @param {Object} dltMst 92024 의 마스터 dataList
 * @returns {Number} arr 길이
 * @hidden N
 */
scwin.getPar = function (arr, dltIsu, dltMst) {
    const data = scwin.getDsclData();

    arr[0] = data.formCd;
    arr[1] = data.bzProcsNo;
    arr[2] = data.isurCd;
    arr[3] = data.mktId;
    if (data.mktId === "1") {
        arr[5] = data.title;
    }

    scwin.fillDataList(dltIsu, data.isu);
    scwin.fillDataList(dltMst, data.mst);

    return arr.length;
};

/**
 * @method
 * @name scwin.fillDataList
 * @author Inswave
 * @date 2026. 10. 29
 * @description 컬럼 정의가 비어 있는 92024 의 원천 dataList 에 행 키를 컬럼으로 더하고 행을 채운다. (원본 CopyDataSet 의 헤더 복사 — §6.11)
 * @param {Object} dataList 채울 dataList (없으면 무시)
 * @param {Array} rows 넣을 행 목록
 * @returns
 * @hidden N
 */
scwin.fillDataList = function (dataList, rows) {
    if (!dataList) return;

    Object.keys(rows[0] ?? {}).forEach(key => {
        if (dataList.getColumnIndex(key) < 0) dataList.insertColumn(key);
    });
    dataList.setJSON(rows);
};

/**
 * @method
 * @name scwin.acntclsMmFormatter
 * @author Inswave
 * @date 2026. 10. 29
 * @description 결산월(일) 표시 — 2자리는 "MM월", 4자리는 "MM월 DD일". 원본은 시장별로 마스크를 바꿨다(유가 MM월 DD일, 코스닥 MM월). (§6.3)
 * @param {String} value 결산월일 원시 값
 * @returns {String} 표시 문자열
 * @hidden N
 */
scwin.acntclsMmFormatter = function (value) {
    const mmdd = String(value ?? "");
    if (mmdd.length === 2) return mmdd + "월";
    if (mmdd.length === 4) return mmdd.substring(0, 2) + "월 " + mmdd.substring(2, 4) + "일";
    return mmdd;
};
